from typing import List

def count_aliens(N: int, M: int, H: List[int]) -> int:
    remaining_disinfectant = M
    alien_count = 0
    for i in range(N):
        if remaining_disinfectant >= H[i]:
            remaining_disinfectant -= H[i]
            alien_count += 1
        else:
            break
    return alien_count
